/** Public API expectations are reviewed static JSON files, never regenerated by these tests. */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';
import { collectRuntimeExportSnapshot, collectTypeExportSnapshots, TYPE_ENTRY_PATHS } from '../scripts/export-snapshot.mjs';

const updateGuidance = 'Review the intended API change, then run node scripts/update-export-snapshots.mjs ' +
  'or npm run snapshot:exports:update explicitly.';

function expectedSnapshot(name) {
  try {
    return JSON.parse(readFileSync(new URL(`./snapshots/${name}`, import.meta.url), 'utf8'));
  } catch (error) {
    throw new Error(`Cannot read the reviewed export snapshot ${name}. ${updateGuidance}`, { cause: error });
  }
}

test('actual CommonJS and ESM runtime exports match the reviewed runtime snapshot', async () => {
  const expected = expectedSnapshot('runtime-exports.json');
  const actual = await collectRuntimeExportSnapshot();
  assert.deepEqual(actual, expected, `The package runtime exports changed. ${updateGuidance}`);
});

let typeSnapshots;
for (const entry of Object.keys(TYPE_ENTRY_PATHS)) {
  test(`${entry} type exports and namespace members match the reviewed type snapshot`, () => {
    const expected = expectedSnapshot('type-exports.json');
    typeSnapshots ??= collectTypeExportSnapshots();
    assert.deepEqual(typeSnapshots[entry], expected, `The ${entry} type exports changed. ${updateGuidance}`);
  });
}
